var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/connection-status-widget.js
type: application/javascript
module-type: widget

Connection onboarding: public metadata only, never API keys.\*/
(function(){
"use strict";
var consent=require("$:/plugins/huwiki/ai/consent.js");
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var adapters=require("$:/plugins/huwiki/ai/model-adapters.js");
var KEY="huwiki-ai-settings-v0.1";
function settings(){try{return JSON.parse(window.localStorage.getItem(KEY)||"{}");}catch(e){return {};}}
function save(v){try{window.localStorage.setItem(KEY,JSON.stringify(v));window.dispatchEvent(new Event("huwiki-ai-connection-change"));}catch(e){}}
function node(parent,name,klass,txt){var e=parent.ownerDocument.createElement(name);if(klass)e.className=klass;if(txt!==undefined)e.textContent=txt;parent.appendChild(e);return e;}
function button(parent,label,fn){var el=node(parent,"button","huwiki-ai-button",label);el.type="button";el.addEventListener("click",fn);return el;}
var bridge=require("$:/plugins/huwiki/ai/forgeshare.js");
function rpc(name,arg){return bridge.rpc(name,arg);}
function openVault(){bridge.pair().catch(function(err){window.alert(err.message);});}
function W(n,o){this.initialise(n,o);}W.prototype=new Widget();
W.prototype.execute=function(){};
W.prototype.render=function(parent,next){this.computeAttributes();if(aiUi.reuseWidget(this,parent,next,"connection-status-widget.js"))return;this.parentDomNode=parent;this.execute();this.root=this.document.createElement("div");this.root.className="huw-ai-connection-status";parent.insertBefore(this.root,next);this.domNodes=[this.root];this.connections=[];this.loaded=false;this.error="";this.validated="";this.answer=null;this.testing=false;this.draw();this.refreshVault();};
W.prototype.refresh=function(changedAiLanguage){if(changedAiLanguage&&changedAiLanguage["$:/language"]){this.draw();return true;}if(this._aiUiDelegate)return this._aiUiDelegate.refresh(changedAiLanguage);return false;};
W.prototype.refreshVault=function(){var self=this;rpc("huPrivateVaultList").then(function(x){
 self.connections=(x&&Array.isArray(x.connections)?x.connections:[]).filter(function(c){return c&&c.id;});self.loaded=true;
 var s=settings();if(self.connections.length&&(!s.vaultId||!self.connections.some(function(c){return c.id===s.vaultId;})||(s.connectionMode!=="vault"&&!s._manualChosen))){s.vaultId=self.connections[0].id;s.connectionMode="vault";s.vaultModels=s.vaultModels||{};save(s);}
 self.draw();
}).catch(function(e){self.loaded=true;self.error=String(e.message||e);self.draw();});};
W.prototype.testAnswer=function(connection,model){
  if(this.testing)return;
  if(!model){this.error=aiUi.text("Vælg først en model i chatten.");this.draw();return;}
  var approval=consent.approve(Object.assign({},connection,{model:model}),{da:aiUi.text('Kun testbeskeden: Svar kun med ordet Klar. Ingen tiddlere.'),en:'Only the test prompt: Reply with the word Ready. No tiddlers.'});
  if(!approval)return;
  var self=this,id=connection.id;
  this.testing=true;this.answer=null;this.error="";this.draw();
  rpc("huPrivateVaultAiGenerate",{
    consent:approval,connectionId:id,model:model,mode:"chat",
    messages:[{role:"user",content:aiUi.text("Svar kun med ordet Klar.")}]
  }).then(function(result){
    if(settings().vaultId!==id)return;
    if(!result||!result.ok||!String(result.content||"").trim())throw Error(aiUi.text("Modellen returnerede et tomt svar."));
    self.answer={id:id,model:model,text:String(result.content).slice(0,300)};
  }).catch(function(error){
    if(settings().vaultId===id)self.error=aiUi.text("AI-svaret kunne ikke hentes: ")+(error.message||error);
  }).then(function(){self.testing=false;self.draw();});
};
W.prototype.draw=function(){var self=this,r=this.root;while(r.firstChild)r.removeChild(r.firstChild);
 consent.notice(r);
 var s=settings(),active=this.connections.find(function(c){return c.id===s.vaultId;})||this.connections[0];
 var title=node(r,"div","huw-ai-connection-title");node(title,"strong",null,aiUi.text("Din AI-forbindelse"));
 if(!this.loaded){node(r,"p",null,aiUi.text("Henter dine gemte forbindelser …"));return;}
 if(this.error){node(r,"p","huw-ai-warning",aiUi.message(this.error));button(r,aiUi.text("Prøv igen"),function(){self.error="";self.refreshVault();});}
 if(!active){node(r,"p",null,aiUi.text("Ingen gemt AI-forbindelse. Opret én for at starte en samtale."));button(r,aiUi.text("Forbind til ForgeShare"),openVault);return;}
 var row=node(r,"div","huw-ai-inline-actions"),label=node(row,"label","huw-ai-connection-picker");node(label,"span",null,aiUi.text("Vælg AI"));var select=node(label,"select","huwiki-ai-input");
 this.connections.forEach(function(c){var opt=node(select,"option",null,c.name+" · "+({gemini:"Gemini",openai:"OpenAI",claude:"Claude",ollama:"Ollama",lmstudio:"LM Studio"}[c.provider]||c.provider));opt.value=c.id;});select.value=active.id;
 select.addEventListener("change",function(){var x=settings();x.vaultId=select.value;x.connectionMode="vault";save(x);self.validated="";self.answer=null;self.error="";self.draw();});
 button(row,aiUi.text("Godkend en anden enhed"),openVault);
 var model=s.vaultModels&&s.vaultModels[active.id]||active.model||"";node(r,"p","huwiki-ai-help",model?aiUi.text("Valgt model: ")+model:aiUi.text("Vælg en model i chatten, eller test forbindelsen."));
 if(this.validated===active.id&&!(this.answer&&this.answer.id===active.id&&this.answer.model===model))node(r,"p","huw-ai-ready",aiUi.text("✓ Modellisten er hentet. Et AI-svar er endnu ikke testet."));
 if(this.answer&&this.answer.id===active.id&&this.answer.model===model)node(r,"p","huw-ai-ready",aiUi.text("✓ AI svarede: ")+this.answer.text);
 if(this.testing)node(r,"p",null,aiUi.text("Venter på et AI-svar…"));
 var actions=node(r,"div","huw-ai-inline-actions");
 if(active){
   var answerButton=button(actions,aiUi.text("Test AI-svar"),function(){self.testAnswer(active,model);});
   answerButton.disabled=this.testing||!model;
 }
 button(actions,aiUi.text("Test forbindelse"),function(){
  self.error="";self.validated="";self.draw();
  var task=rpc("huPrivateVaultAiModels",active.id).then(function(d){return d.models||[];});
  task.then(function(models){self.validated=active.id;var chosen=model||adapters.preferCloudModel(active.provider,models,"");if(chosen){var x=settings();x.vaultModels=x.vaultModels||{};x.vaultModels[active.id]=chosen;save(x);}self.draw();}).catch(function(e){self.error=aiUi.text("Forbindelsen svarede ikke: ")+(e.message||e);self.draw();});
 });
};
exports["huwiki-ai-connection-status"]=W;
})();
